import React, { useState } from 'react';
import toast from 'react-hot-toast';
import { login } from '../services/api';
import { Lock, Mail } from 'lucide-react';

export default function LoginPage({ onLogin }) {
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!password) return;
    setLoading(true);
    try {
      await login(password);
      toast.success('Welcome back!');
      onLogin();
    } catch {
      toast.error('Invalid password. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-page">
      <div className="login-card glass">
        <div className="login-icon-wrapper">
          <div className="login-icon">
            <Mail size={40} strokeWidth={2.5} />
          </div>
        </div>
        <h1 className="text-gradient">Payments Portal</h1>
        <p className="login-subtitle">Secure Reconciliation Dashboard</p>

        <form onSubmit={handleSubmit} className="login-form">
          <div className="form-group">
            <label>Admin Access</label>
            <div className="input-container">
              <Lock size={18} className="input-icon" />
              <input
                type="password"
                className="has-icon"
                placeholder="••••••••"
                value={password}
                onChange={e => setPassword(e.target.value)}
                autoFocus
              />
            </div>
          </div>

          <button type="submit" disabled={loading} className="btn btn-primary btn-full" style={{ padding: '14px' }}>
            {loading ? <div className="spinner" style={{ width: '20px', height: '20px', borderTopColor: 'white' }} /> : 'Authenticate'}
          </button>
        </form>
      </div>
    </div>
  );
}
